  unsubscribeUrl: string;
}

const baseUrl = process.env.NEXT_PUBLIC_APEX_URL
  ? `https://${process.env.NEXT_PUBLIC_APEX_URL}`
  : "https://hastoggle.dev";

function DigestEmail({
  title,
  misconception,
  content,
  series,
  archiveUrl,
  unsubscribeUrl,
}: DigestEmailProps): ReactElement {
  return (
    <Html>
      <Head />
      <Preview>{title}</Preview>
      <Body style={main}>
        <Container style={container}>
          <Img
            alt="hasToggle"
            height={42}
            src={`${baseUrl}/icon.png`}
            width={42}
          />
          {series ? (
            <Text style={seriesLabel}>
              {series.name} &mdash; Part {series.part}
            </Text>
          ) : null}
          <Heading style={heading}>{title}</Heading>
          <Text style={misconceptionStyle}>
            Misconception: &ldquo;{misconception}&rdquo;
          </Text>
          <Hr style={hr} />
